/**
 * Splits files for processing.
 * All Rayvn files need HTTP GET via SAS.
 */
const entry = msg.payload;
const items = msg.metadata.files.items;
const total = items.length;

const dl = {
    entry_backup: JSON.parse(JSON.stringify(entry, (k, v) => k === '_buffer' ? undefined : v)),
    connection_name: msg.metadata.connection_name,
    message_id: entry.id,
    metadata: msg.metadata
};

const to_download = [];

items.forEach((file, i) => {
    const parts = { id: msg._msgid, type: "array", count: total, index: i };

    to_download.push({
        _msgid: msg._msgid,
        payload: file,
        metadata: msg.metadata,
        _dl: dl,
        parts: parts,
        _file_meta: {
            url: file.url,
            name: file.name || "unknown_file",
            type: file.type || "application/octet-stream",
            size: file.size || 0
        }
    });
});

return to_download.length ? [to_download] : null;

/**
 * Stores the downloaded file buffer in global context.
 * Returns a pruned file result object for the join node.
 */
const utils = global.get("utils");
const meta = msg._file_meta;
const dl = msg._dl;
const success = msg.statusCode === 200 && msg.payload && msg.payload.length > 0;

const file = { name: meta.name, type: meta.type, size: meta.size, downloaded: success };

if (success) {
    const key = utils.build_file_key(dl.message_id, dl.connection_name, meta.name);
    global.set("files." + key, msg.payload);
    file.context_key = key;
} else {
    node.warn("[BOOST] File download failed. Status: " + msg.statusCode + ", file: " + meta.name);
}

return {
    _msgid: msg._msgid,
    topic: msg.topic,
    payload: file,
    parts: msg.parts,
    _dl: msg._dl
};

const utils = global.get("utils");
const dl = msg._dl;
const entry = dl.entry_backup;
const metadata = dl.metadata;
const downloaded = Array.isArray(msg.payload) ? msg.payload : [msg.payload];

// Separate stored files from failures
const stored = downloaded.filter(f => f.downloaded);
const failed = downloaded
    .filter(f => !f.downloaded)
    .map(f => ({ name: f.name || "ukjent fil", reason: f.reason || utils.FILE_REASONS.DOWNLOAD_FAILED }));

// Update entry
entry.files = stored;
entry.failed_files = [...(entry.failed_files || []), ...failed];

// Sync metadata.files contract for POST side
metadata.files.items = stored;
metadata.files.failed = [...metadata.files.failed, ...failed];

node.log("[BOOST] File download complete for entry " + entry.id + ": "
    + stored.length + " stored, " + failed.length + " failed");

return {
    _msgid: msg._msgid,
    topic: msg.topic,
    payload: entry,
    metadata: metadata
};

const session = global.get("parat_bridge.ropc_session");
if (!session) {
    node.warn("[BOOST] No ROPC session — cannot download file");
    msg.payload = null;
    return msg;
}

const file = msg._file_meta;

// Pick correct SAS token based on URL pattern
let sasToken;
if (file.url.includes("blob.core.windows.net")) {
    sasToken = session.filesAccessToken;
} else {
    sasToken = session.imagesAccessToken;
}

msg.url = file.url + "?" + sasToken;
msg.headers = {};  // SAS handles auth, no header needed
return msg;
